 if(king){c.beginPath();c.moveTo(-12,3);c.quadraticCurveTo(-15,16,-5,19);c.lineTo(0,23);c.lineTo(6,19);c.quadraticCurveTo(16,15,12,3);c.quadraticCurveTo(8,8,7,10);c.quadraticCurveTo(0,15,-7,10);c.quadraticCurveTo(-8,6,-12,3);c.fillStyle='#aa7a4d';c.fill();c.strokeStyle='#7e6046';c.lineWidth=1;c.stroke();for(const sign of [-1,1]){c.beginPath();c.moveTo(0,5);c.quadraticCurveTo(sign*4,1,sign*9,6);c.quadraticCurveTo(sign*4,10,0,7);c.fillStyle='#8a6343';c.fill();}line(c,[[-5,15],[-3,19]],'#d9b780',1);line(c,[[4,15],[2,20]],'#d9b780',1);}
