 const backHand=dead?[-23,-6]:archer?[3-strike*13,shoulder+6]:king?[-20,hip+2]:[-19-stride*.4,hip+3];arm(c,[-12,shoulder+4],[-19,shoulder+15],backHand,archer?'#7c947b':p.dark,knight,skin);
 for(const sign of [-1,1]){const foot=sign*7+sign*stride,lift=walking&&!dead?Math.max(0,-sign*step)*4:0,kx=sign*7+sign*stride*.45,ky=dead?-11:hip*.48;line(c,[[sign*6,hip],[kx,ky],[foot,-5-lift]],INK,9);line(c,[[sign*6,hip],[kx,ky],[foot,-5-lift]],knight?'#91a5af':archer?'#6e755d':king?'#6f6078':p.dark,6.5);if(knight){oval(c,kx,ky,4.8,4.3,'#c5d1cf',INK,1);line(c,[[kx+1,ky+4],[foot+1,-7-lift]],'#dce5dc',1.3);}box(c,foot-6,-7-lift,15,7,2.8,knight?'#899fa7':'#6c574a',INK,1.3);line(c,[[foot-3,-1.5-lift],[foot+6,-1.5-lift]],knight?'#d1dcd4':'#bba37e',1);}
