/** Velocity-aligned projectiles; positive local x points forward. */
export function drawCastleMissile(ctx,p={}){const c=ctx,type=p.type||p.weapon||p.kind||(p.slow?'frost':p.splash?'stone':'arrow'),vx=num(p.vx),vy=num(p.vy),angle=vx||vy?Math.atan2(vy,vx):num(p.angle),r=clamp(num(p.r,5),2,18),s=clamp(num(p.scale,1),.1,6),friendly=p.owner==='castle'||p.side===0;c.save();c.translate(num(p.x),num(p.y));c.rotate(angle);c.scale(s,s);c.lineCap='round';c.lineJoin='round';if(type==='royal'){const size=4+(p.level||1)*.6;c.fillStyle='#e3b85d';c.strokeStyle='#fff2b4';c.lineWidth=1.5;c.beginPath();for(let i=0;i<10;i++){const a=i*Math.PI/5-Math.PI/2,r=i%2?size*.42:size;i?c.lineTo(Math.cos(a)*r,Math.sin(a)*r):c.moveTo(Math.cos(a)*r,Math.sin(a)*r);}c.closePath();c.fill();c.stroke();line(c,[[-size*3,0],[-size,0]],'#e0c26b80',2);}else if(type==='cannonball'||type==='cannon'){line(c,[[-r*2.8,-r*.25],[-r*1.2,-r*.25]],'#8c81744a',2);oval(c,0,0,r,r,grad(c,-r,-r,r,r,[[0,'#a5b1ab'],[.35,'#60767a'],[1,'#304953']]),'#30464d',1.3);oval(c,-r*.3,-r*.3,r*.24,r*.18,'#e5e7d1');}
 else if(type==='stone'||type==='catapult'){path(c,Array.from({length:7},(_,i)=>{const a=i*TAU/7,rr=r*(i%2?.93:1.15);return[Math.cos(a)*rr,Math.sin(a)*rr];}),grad(c,-r,-r,r,r,[[0,'#d1cab5'],[1,'#949e91']]),'#65716b',1.4);line(c,[[-r*.6,-r*.4],[r*.05,-r*.66],[r*.48,-r*.05]],'#e6e2cb',1.5);line(c,[[-r*.25,r*.24],[r*.4,r*.42]],'#748178',1);}
 else if(type==='frost'){line(c,[[-22,0],[-8,0]],'#addce066',3);path(c,[[-12,-3],[4,-6],[15,0],[4,6],[-12,3],[-7,0]],'#d0ece8','#6a9daa',1.3);line(c,[[-6,0],[12,0]],'#fff8e0',1.7);line(c,[[3,-4],[3,4]],'#f2faf0',1);}
 else{const bolt=type==='bolt'||type==='ballista',length=bolt?28:35,tail=bolt?-length*.5:-length*.58;line(c,[[tail,0],[length*.35,0]],'#625b49',bolt?3.7:2.8);line(c,[[tail,0],[length*.35,0]],bolt?'#95724e':'#c6a472',bolt?2.2:1.5);path(c,[[length*.28,-(bolt?4:3)],[length*.56,0],[length*.28,bolt?4:3],[length*.34,0]],bolt?'#9db2b5':'#cdd9d3','#627880',.8);for(const sign of [-1,1])path(c,[[tail+2,0],[tail-4,sign*(bolt?5:4)],[tail+4,sign*(bolt?5:4)],[tail+10,0]],friendly?'#84b0ba':'#c18d8b','#606e6d',.7);line(c,[[tail-3,-1],[tail-3,1]],'#e6dfbb',1);}c.restore();}
