/** Inline SVG icons for every existing CASTLE_PARTS id, plus footman. */
export function castleItemIcon(type){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" aria-hidden="true" fill="none" stroke="#526960" stroke-width="2.2" stroke-linejoin="round" stroke-linecap="round">${ICONS[type]||ICONS.stone}</svg>`;}
